    <script>
        /**
         * MESOSKETCH - Core Logic
         * Handles Canvas rendering, Noise generation, and Interactive State.
         */

        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');

        // State Management
        const state = {
            seed: Math.random() * 10000,
            complexity: 100,
            heightMultiplier: 400,
            chaos: 0.2,
            timeOfDay: 16, // 0-24
            showSun: true,
            showTrees: true,
            width: window.innerWidth,
            height: window.innerHeight
        };

        // Pseudo-Random Number Generator (Seeded)
        class SimpleNoise {
            constructor(seed) {
                this.seed = seed;
            }

            // Helper to get noise between -1 and 1
            next(x) {
                const n = Math.sin(x * this.seed) * 10000;
                return n - Math.floor(n);
            }

            // 2D Noise approximation
            noise2D(x, z) {
                const val = Math.sin(x * 1.5 + this.seed) + Math.sin(z * 2.3 + this.seed * 1.5) + Math.sin((x + z) * 0.7);
                return val / 2; // Normalize approx
            }
        }

        let noiseGen = new SimpleNoise(state.seed);

        // Resize Handler
        function resize() {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
            state.width = canvas.width;
            state.height = canvas.height;
            draw();
        }
        window.addEventListener('resize', resize);

        // Color Palettes
        function getSkyColor(t) {
            // t is 0-24, representing time
            // Colors: [R, G, B]

            const midnight = [10, 15, 30];
            const dawn = [255, 150, 100];
            const noon = [135, 206, 235];
            const dusk = [200, 80, 120];

            let c1, c2, factor;

            // Normalize time for lerp
            if (t >= 0 && t < 5) { // Night to Dawn
                c1 = midnight; c2 = midnight; factor = 0;
            } else if (t >= 5 && t < 8) { // Dawn
                c1 = midnight; c2 = dawn; factor = (t - 5) / 3;
            } else if (t >= 8 && t < 12) { // Morning
                c1 = dawn; c2 = noon; factor = (t - 8) / 4;
            } else if (t >= 12 && t < 17) { // Afternoon
                c1 = noon; c2 = noon; factor = 0;
            } else if (t >= 17 && t < 20) { // Dusk
                c1 = noon; c2 = dusk; factor = (t - 17) / 3;
            } else { // Night
                c1 = dusk; c2 = midnight; factor = (t - 20) / 4;
            }

            // Simple linear interpolation for RGB
            const r = Math.floor(c1[0] + (c2[0] - c1[0]) * factor);
            const g = Math.floor(c1[1] + (c2[1] - c1[1]) * factor);
            const b = Math.floor(c1[2] + (c2[2] - c1[2]) * factor);

            return `rgb(${r}, ${g}, ${b})`;
        }

