            const { width, height, timeOfDay } = state;

            // 1. Background (Sky)
            const skyColor = getSkyColor(timeOfDay);
            const grad = ctx.createLinearGradient(0, 0, 0, height);
            grad.addColorStop(0, skyColor);
            grad.addColorStop(1, '#ffffff'); // Horizon haze
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, width, height);

            // 2. Celestial Bodies
            if (state.showSun) {
                // Calculate sun/moon position based on time
                // Arc from left to right
                const cx = width / 2;
                const cy = height;
                const radius = Math.min(width, height) * 0.8;
                const angle = ((timeOfDay - 6) / 14) * Math.PI; // Map 6am to 8pm to 0-PI

                // Clamp angle for nighttime visuals
                let sunX, sunY;
                if (timeOfDay >= 6 && timeOfDay <= 20) {
                    sunX = cx - Math.cos(angle) * (width * 0.4);
                    sunY = cy - Math.sin(angle) * (height * 0.8);

                    // Draw Sun
                    ctx.beginPath();
                    ctx.arc(sunX, sunY, 40, 0, Math.PI * 2);
                    ctx.fillStyle = 'rgba(255, 255, 200, 0.9)';
                    ctx.shadowBlur = 50;
                    ctx.shadowColor = 'rgba(255, 200, 50, 0.8)';
                    ctx.fill();
                    ctx.shadowBlur = 0;

                    // Sun Glow on horizon
                    const horizonGrad = ctx.createLinearGradient(width/2, height * 0.6, width/2, height);
                    horizonGrad.addColorStop(0, 'rgba(255, 255, 255, 0)');
                    horizonGrad.addColorStop(0.5, 'rgba(255, 200, 100, 0.2)');
                    horizonGrad.addColorStop(1, 'rgba(255, 100, 50, 0.4)');
                    ctx.fillStyle = horizonGrad;
                    ctx.fillRect(0, height * 0.6, width, height * 0.4);
                } else {
                    // Draw Moon
                    const moonAngle = ((timeOfDay > 20 ? timeOfDay - 20 : timeOfDay + 4) / 10) * Math.PI;
                    sunX = cx - Math.cos(moonAngle) * (width * 0.4);
                    sunY = cy - Math.sin(moonAngle) * (height * 0.8);

                    ctx.beginPath();
                    ctx.arc(sunX, sunY, 30, 0, Math.PI * 2);
