            --matrix-dark: #000;
            --matrix-dim: #003b00;
        }

        body {
            background-color: var(--matrix-dark);
            color: var(--matrix-green);
            font-family: 'Share Tech Mono', monospace;
            overflow: hidden;
            margin: 0;
            padding: 0;
            cursor: crosshair;
        }

        /* CRT Scanline Effect */
        .scanline {
            width: 100%;
            height: 100px;
            z-index: 10;
            background: linear-gradient(0deg, rgba(0,0,0,0) 0%, rgba(0, 255, 0, 0.04) 50%, rgba(0,0,0,0) 100%);
            opacity: 0.1;
            position: absolute;
            bottom: 100%;
            animation: scanline 10s linear infinite;
            pointer-events: none;
        }

        @keyframes scanline {
            0% { bottom: 100%; }
            100% { bottom: -100px; }
        }

        /* Poster Container 3D */
        .poster-container {
            perspective: 1000px;
            transform-style: preserve-3d;
        }

        .poster-card {
            transform-style: preserve-3d;
            transition: transform 0.1s ease-out;
            box-shadow: 0 0 20px rgba(0, 255, 0, 0.2);
        }

        /* Glitch Text */
        .glitch {
            position: relative;
        }
        .glitch::before, .glitch::after {
            content: attr(data-text);
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: #000;
        }
        .glitch::before {
            left: 2px;
            text-shadow: -1px 0 #ff00c1;
            clip: rect(44px, 450px, 56px, 0);
            animation: glitch-anim 5s infinite linear alternate-reverse;
        }
        .glitch::after {
            left: -2px;
            text-shadow: -1px 0 #00fff9;
            clip: rect(44px, 450px, 56px, 0);
            animation: glitch-anim2 5s infinite linear alternate-reverse;
        }

        @keyframes glitch-anim {
            0% { clip: rect(3px, 9999px, 8px, 0); }
            5% { clip: rect(32px, 9999px, 96px, 0); }
            10% { clip: rect(12px, 9999px, 65px, 0); }
            15% { clip: rect(89px, 9999px, 12px, 0); }
            20% { clip: rect(12px, 9999px, 89px, 0); }
            100% { clip: rect(54px, 9999px, 11px, 0); }
        }
        @keyframes glitch-anim2 {
            0% { clip: rect(65px, 9999px, 100px, 0); }
            100% { clip: rect(12px, 9999px, 5px, 0); }
        }

        /* Custom Scrollbar for terminal */
        ::-webkit-scrollbar {
            width: 5px;
        }
        ::-webkit-scrollbar-track {
            background: #000; 
        }
        ::-webkit-scrollbar-thumb {
            background: #0f0; 
        }

        .glass-panel {
            background: rgba(0, 20, 0, 0.7);
            backdrop-filter: blur(4px);
            border: 1px solid rgba(0, 255, 0, 0.3);
        }

        .matrix-btn {
            background: linear-gradient(180deg, #001a00 0%, #000 100%);
            border: 1px solid #0f0;
            color: #0f0;
            text-transform: uppercase;
            letter-spacing: 2px;
            transition: all 0.2s;
            box-shadow: 0 0 5px #0f0;
        }
        .matrix-btn:hover {
            background: #0f0;
            color: #000;
            box-shadow: 0 0 15px #0f0;
        }
        .matrix-btn:active {
            transform: scale(0.98);
        }

        .hologram-ring {
            border: 2px solid rgba(0, 255, 0, 0.5);
            border-radius: 50%;
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            box-shadow: 0 0 15px rgba(0, 255, 0, 0.3);
            animation: pulse-ring 4s infinite ease-in-out;
            pointer-events: none;
        }

        @keyframes pulse-ring {
            0% { width: 90%; height: 90%; opacity: 0.3; }
            50% { width: 95%; height: 95%; opacity: 0.1; }
            100% { width: 90%; height: 90%; opacity: 0.3; }
        }

        /* Toast Notification */
        .toast {
            transform: translateX(120%);
            transition: transform 0.3s cubic-bezier(0.68, -0.55, 0.27, 1.55);
        }
        .toast.show {
            transform: translateX(0);
        }

    </style>
</head>
