            <div class="bg-slate-800/50 border border-slate-700 rounded-2xl p-6 shadow-xl backdrop-blur-sm">
                <h2 class="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                    <svg class="w-5 h-5 text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
                    Configuration
                </h2>

                <!-- Slider -->
                <div class="mb-8">
                    <div class="flex justify-between mb-2">
                        <label class="text-sm font-medium text-slate-300">Term Count (n)</label>
                        <span id="n-value-display" class="text-sm font-bold text-blue-400 mono bg-blue-400/10 px-2 py-0.5 rounded">20</span>
                    </div>
                    <input type="range" id="n-slider" min="2" max="100" value="20" class="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer">
                    <div class="flex justify-between mt-1 text-xs text-slate-500">
                        <span>2</span>
                        <span>100</span>
                    </div>
                </div>

                <!-- Buttons -->
                <div class="grid grid-cols-2 gap-3 mb-6">
                    <button id="btn-generate" class="col-span-2 bg-blue-600 hover:bg-blue-500 text-white font-semibold py-3 px-4 rounded-xl transition-all shadow-lg shadow-blue-600/20 active:scale-[0.98] flex justify-center items-center gap-2">
                        <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                        Generate / Reset
                    </button>

                    <button id="btn-play" class="bg-slate-700 hover:bg-slate-600 text-white font-medium py-2 px-4 rounded-lg transition-colors flex justify-center items-center gap-2">
                        <svg id="icon-play" class="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                        <span id="text-play">Auto Step</span>
                    </button>

                    <button id="btn-formula" class="bg-slate-700 hover:bg-slate-600 text-white font-medium py-2 px-4 rounded-lg transition-colors flex justify-center items-center gap-2">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"></path></svg>
                        Binet's Mode
                    </button>
                </div>

                <!-- Speed Control -->
                <div class="flex items-center justify-between bg-slate-900/50 p-3 rounded-lg border border-slate-700/50">
                    <span class="text-xs text-slate-400">Visual Speed</span>
                    <input type="range" id="speed-slider" min="50" max="1000" value="300" class="w-24 h-1 bg-slate-600 rounded-lg appearance-none cursor-pointer">
                </div>
            </div>

            <!-- Golden Ratio Stats -->
            <div class="bg-slate-800/50 border border-slate-700 rounded-2xl p-6 shadow-xl relative overflow-hidden">
                <div class="absolute top-0 right-0 w-32 h-32 bg-yellow-500/5 rounded-full blur-3xl -mr-10 -mt-10 pointer-events-none"></div>

                <h3 class="text-sm font-medium text-slate-400 uppercase tracking-wider mb-3">Golden Ratio (φ)</h3>
                <div class="flex items-baseline gap-2">
                    <span id="golden-ratio-display" class="text-4xl font-bold text-yellow-400 mono tracking-tighter">1.000</span>
                    <span class="text-xs text-slate-500 self-end mb-1">(Target: 1.618...)</span>
                </div>
                <div class="mt-4 w-full bg-slate-700 h-1.5 rounded-full overflow-hidden">
                    <div id="golden-bar" class="h-full bg-yellow-400 w-0 transition-all duration-1000"></div>
                </div>
                <p class="mt-3 text-xs text-slate-400 leading-relaxed">
                    As n increases, the ratio of consecutive Fibonacci numbers approaches the Golden Ratio.
                </p>
            </div>

            <!-- Code Reference -->
            <div class="bg-slate-900 border border-slate-800 rounded-xl p-4 text-xs mono text-slate-300 overflow-hidden">
                <div class="flex justify-between mb-2 border-b border-slate-800 pb-2">
                    <span class="text-blue-400 font-bold">fibonacci.js</span>
                    <span class="text-slate-500">Read-only</span>
                </div>
                <pre><code><span class="text-purple-400">function</span> <span class="text-blue-300">fib</span>(n) {
  <span class="text-purple-400">if</span> (n < 2) <span class="text-purple-400">return</span> n;
  <span class="text-purple-400">return</span> <span class="text-blue-300">fib</span>(n-1) + <span class="text-blue-300">fib</span>(n-2);
}</code></pre>
            </div>

        </section>

        <!-- Right Panel: Visualization & Output -->
        <section class="lg:col-span-8 flex flex-col gap-6 h-full">

            <!-- Chart Section -->
            <div class="bg-slate-800/50 border border-slate-700 rounded-2xl p-1 shadow-xl flex flex-col h-64 md:h-80 relative group">
                <canvas id="fib-chart" class="w-full h-full rounded-xl bg-slate-900/50 cursor-crosshair"></canvas>

                <!-- Tooltip Overlay -->
                <div id="chart-tooltip" class="absolute hidden pointer-events-none bg-slate-800 border border-slate-600 text-white text-xs p-2 rounded shadow-xl z-10">
                    <span class="font-bold text-blue-400 block mb-1">F(<span class="idx">0</span>)</span>
                    <span class="val mono">0</span>
                </div>

                <div class="absolute top-4 right-4 bg-slate-800/80 backdrop-blur px-3 py-1 rounded-full border border-slate-700 text-xs text-slate-400">
                    Logarithmic Scale (Visual Only)
                </div>
            </div>

            <!-- Sequence Grid -->
            <div class="flex-grow bg-slate-800/30 border border-slate-700 rounded-2xl p-6 overflow-hidden flex flex-col">
                <div class="flex justify-between items-end mb-4">
                    <h2 class="text-lg font-semibold text-white">Sequence Output</h2>
                    <div class="flex gap-2 text-xs">
                        <span class="px-2 py-1 rounded bg-slate-700 text-slate-300">Total: <span id="total-terms" class="text-white font-bold">0</span></span>
                    </div>
                </div>

                <!-- The Grid -->
                <div id="sequence-grid" class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 overflow-y-auto pr-2 pb-2 max-h-[500px] content-start">
                    <!-- Items injected via JS -->
                </div>
            </div>

        </section>
    </main>

    <!-- Footer -->
    <footer class="mt-auto border-t border-slate-800 bg-slate-900 py-6">
        <div class="max-w-7xl mx-auto px-4 text-center text-slate-500 text-sm">
            <p>Generated for Interactive Fibonacci Visualization.</p>
        </div>
    </footer>

    <script>
        /**
         * Application State & Configuration
         */
        const state = {
            n: 20,
            sequence: [],
            isPlaying: false,
            playInterval: null,
            speed: 300,
            mode: 'iterative', // 'iterative' or 'binet'
            currentIndex: 0 // for animation
        };

        // DOM Elements
        const els = {
            slider: document.getElementById('n-slider'),
            display: document.getElementById('n-value-display'),
            grid: document.getElementById('sequence-grid'),
            chart: document.getElementById('fib-chart'),
            btnGenerate: document.getElementById('btn-generate'),
            btnPlay: document.getElementById('btn-play'),
            btnFormula: document.getElementById('btn-formula'),
            iconPlay: document.getElementById('icon-play'),
            textPlay: document.getElementById('text-play'),
            speedSlider: document.getElementById('speed-slider'),
            goldenRatio: document.getElementById('golden-ratio-display'),
            goldenBar: document.getElementById('golden-bar'),
            totalTerms: document.getElementById('total-terms'),
            tooltip: document.getElementById('chart-tooltip')
        };

        const ctx = els.chart.getContext('2d');

        /**
         * Core Logic: Fibonacci Calculation
         */

        // Iterative approach (Fast & Accurate for n < 1000)
        function generateFibonacci(n) {
            const seq = [0n, 1n];
            for (let i = 2; i < n; i++) {
                seq.push(seq[i - 1] + seq[i - 2]);
            }
            return seq.slice(0, n);
        }

        // Binet's Formula (Approximation for large n, but precise for integers up to a point)
        // F(n) = (phi^n - psi^n) / sqrt(5)
        // Note: JS Number precision limits this around n=70. We use it for visual effect mostly.

