        // --- Procedural Texture Generators ---

        function createNoiseTexture(baseColorHex, scale = 1) {
            const size = 512;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            ctx.fillStyle = baseColorHex;
            ctx.fillRect(0,0,size,size);

            const imageData = ctx.getImageData(0,0,size,size);
            const data = imageData.data;

            for(let i = 0; i < data.length; i += 4) {
                const grain = (Math.random() - 0.5) * 30 * scale;
                data[i] = Math.min(255, Math.max(0, data[i] + grain));
                data[i+1] = Math.min(255, Math.max(0, data[i+1] + grain));
                data[i+2] = Math.min(255, Math.max(0, data[i+2] + grain));
            }
            ctx.putImageData(imageData, 0, 0);

            const tex = new THREE.CanvasTexture(canvas);
            tex.wrapS = THREE.RepeatWrapping;
            tex.wrapT = THREE.RepeatWrapping;
            return tex;
        }

        function createWoodTexture(colorHex) {
            const size = 1024;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            ctx.fillStyle = colorHex;
            ctx.fillRect(0,0,size,size);

            // Draw wood grain
            ctx.globalAlpha = 0.1;
            ctx.globalCompositeOperation = 'multiply';

            for(let i=0; i<300; i++) {
                ctx.beginPath();
                ctx.moveTo(Math.random() * size, 0);
                ctx.bezierCurveTo(
                    Math.random() * size, size * 0.3,
                    Math.random() * size, size * 0.6,
                    Math.random() * size, size
                );
                ctx.strokeStyle = '#000';
                ctx.lineWidth = 1 + Math.random() * 3;
                ctx.stroke();
            }

            const tex = new THREE.CanvasTexture(canvas);
            tex.wrapS = THREE.RepeatWrapping;
            tex.wrapT = THREE.RepeatWrapping;
            tex.repeat.set(2, 2);
            return tex;
        }

        function createFabricTexture(colorHex) {
            const size = 256;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            ctx.fillStyle = colorHex;
            ctx.fillRect(0,0,size,size);

            ctx.strokeStyle = 'rgba(0,0,0,0.1)';
            ctx.lineWidth = 1;

            // Crosshatch
            for(let i=0; i<size; i+=4) {
                ctx.beginPath();
                ctx.moveTo(0, i); ctx.lineTo(size, i);
                ctx.moveTo(i, 0); ctx.lineTo(i, size);
                ctx.stroke();
            }

            const tex = new THREE.CanvasTexture(canvas);
            tex.wrapS = THREE.RepeatWrapping;
            tex.wrapT = THREE.RepeatWrapping;
            tex.repeat.set(4, 4);
            return tex;
        }

        function createRugTexture(style) {
             const size = 512;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            if(style === 'solid') {
                ctx.fillStyle = '#3b82f6';
                ctx.fillRect(0,0,size,size);
                // Border
                ctx.strokeStyle = '#fbbf24';
                ctx.lineWidth = 20;
                ctx.strokeRect(10,10,size-20, size-20);
            } else if (style === 'pattern') {
                ctx.fillStyle = '#b45309';
                ctx.fillRect(0,0,size,size);
                ctx.fillStyle = '#92400e';
                for(let i=0; i<10; i++) {
                    for(let j=0; j<10; j++) {
                        if((i+j)%2===0) ctx.fillRect(i*51.2, j*51.2, 51.2, 51.2);
                    }
                }
            } else {
                return null; // No rug
            }

            const tex = new THREE.CanvasTexture(canvas);
            tex.wrapS = THREE.RepeatWrapping;
            tex.wrapT = THREE.RepeatWrapping;
            return tex;
        }

