    <style>
        :root {
            --neon-blue: #00f3ff;
            --neon-pink: #ff00ff;
            --deep-space: #05050b;
            --glass: rgba(255, 255, 255, 0.05);
        }

        body {
            font-family: 'Inter', sans-serif;
            background-color: var(--deep-space);
            color: white;
            overflow-x: hidden;
            margin: 0;
        }

        h1, h2, h3 {
            font-family: 'Space Grotesk', sans-serif;
        }

        /* Custom Scrollbar */
        ::-webkit-scrollbar {
            width: 8px;
        }
        ::-webkit-scrollbar-track {
            background: #000;
        }
        ::-webkit-scrollbar-thumb {
            background: #333;
            border-radius: 4px;
        }
        ::-webkit-scrollbar-thumb:hover {
            background: var(--neon-blue);
        }

        /* Cosmos Background */
        #star-canvas {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: -1;
            pointer-events: none;
        }

        /* Perspective Container */
        .viewport {
            perspective: 1200px;
            height: 100vh;
            width: 100%;
            overflow-y: auto;
            overflow-x: hidden;
            position: relative;
            scroll-behavior: smooth; /* For navigation clicks */
        }

        /* The Timeline Track (The vertical invisible ladder) */
        .timeline-track {
            position: absolute;
            left: 50%;
            transform: translateX(-50%);
            top: 0;
            width: 4px;
            height: 100%;
            background: linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(255,255,255,0.1) 10%, rgba(255,255,255,0.1) 90%, rgba(0,0,0,0) 100%);
            z-index: 10;
        }

        /* Event Cards Sticky Logic Wrapper */
        .era-marker {
            height: 800px; /* Spacing between events */
            width: 100%;
            position: relative;
            display: flex;
            justify-content: center;
            align-items: center;
            transform-style: preserve-3d;
            /* opacity: 0.1; start hidden */
            transition: opacity 0.5s;
        }

        .era-marker.active {
            opacity: 1;
        }

        /* The Card */
        .geocard {
            position: sticky;
            top: 20vh; /* Sticks at 20% from top */
            width: 85%;
            max-width: 800px;
            background: rgba(15, 23, 42, 0.8);
            backdrop-filter: blur(12px);
            border: 1px solid rgba(255,255,255,0.1);
            border-radius: 20px;
            padding: 2rem;
            box-shadow: 0 20px 50px rgba(0,0,0,0.5);
            transform-style: preserve-3d;
            transition: transform 0.2s ease-out, border-color 0.3s;
            display: flex;
            flex-direction: column;
            gap: 1rem;
        }

        .geocard::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 4px;
            background: var(--neon-blue);
            border-radius: 20px 20px 0 0;
            opacity: 0.5;
        }

        .geocard:hover::before {
            opacity: 1;
            box-shadow: 0 0 15px var(--neon-blue);
        }

        /* 3D Tilt Effect handled via JS */

        .time-label {
            font-variant-numeric: tabular-nums;
            font-family: 'Space Grotesk', sans-serif;
            font-size: 4rem;
            font-weight: 700;
            opacity: 0.1;
            line-height: 1;
            position: absolute;
            right: -50px;
            top: 50%;
            transform: translateY(-50%) rotate(-90deg);
            white-space: nowrap;
            color: var(--neon-blue);
            pointer-events: none;
            z-index: 0;
        }

        /* Connecting Line to center */
        .connector-line {
            position: absolute;
            top: 50%;
            height: 2px;
            background: linear-gradient(90deg, var(--neon-blue), transparent);
            z-index: 5;
        }
        .card-left .connector-line {
            left: 100%;
            width: 100px; 
        }
        .card-right .connector-line {
            right: 100%;
            width: 100px;
            background: linear-gradient(270deg, var(--neon-blue), transparent);
        }

        /* Navigation Dots */
        .nav-dot {
            width: 12px;
            height: 12px;
            border-radius: 50%;
            background: #333;
            border: 2px solid #555;
            transition: all 0.3s;
            cursor: pointer;
        }
        .nav-dot.active {
            background: var(--neon-blue);
            border-color: white;
            box-shadow: 0 0 10px var(--neon-blue);
        }

        /* Earth Model Container */
        .earth-container {
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            z-index: 0;
            pointer-events: none;
            opacity: 0.3; /* Ghostly background earth */
            transition: opacity 0.5s;
        }
        .earth-active .earth-container {
            opacity: 0.6;
        }

        /* Floating Particles */
        .particle {
            position: absolute;
            background: white;
            border-radius: 50%;
            opacity: 0;
            pointer-events: none;
        }

        @keyframes floatUp {
            0% { transform: translateY(0) scale(1); opacity: 0.8; }
            100% { transform: translateY(-100px) scale(0); opacity: 0; }
        }

        /* Utility */
        .text-gradient {
            background: linear-gradient(to right, #fff, #a5f3fc);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        /* Mobile Adjustments */
        @media (max-width: 768px) {
            .geocard {
                width: 90%;
                top: 15vh;
            }
            .timeline-track {
                left: 20px;
            }
            .nav-dots-container {
                right: 10px;
            }
        }
    </style>
</head>
